using System.Windows; using System.Windows.Controls; namespace DocumentManagement.Views.Updates; public partial class UpdateReadyView:UserControl { public event EventHandler? InstallRequested; public event EventHandler? LaterRequested; public UpdateReadyView(){InitializeComponent();} public void Configure(string version)=>DetailsText.Text=$"Phiên bản {version} đã tải xong. Ứng dụng sẽ đóng và mở lại để cài đặt."; public void SetInstalling(bool value){InstallButton.IsEnabled=!value; if(value)InstallButton.Content="Đang chuẩn bị...";} private void Install_Click(object s,RoutedEventArgs e)=>InstallRequested?.Invoke(this,EventArgs.Empty); private void Later_Click(object s,RoutedEventArgs e)=>LaterRequested?.Invoke(this,EventArgs.Empty); }
